type QAReproductionRequest struct {
	Project          string
	Sprint           string
	TargetRoot       string
	WorkspaceParent  string
	ProtectedRoots   []string
	Spec             QAReproductionSpec
	Bundle           QATestBundle
	Budgets          QABudgets
	Runner           pprocess.Runner
	ExpectedTargetID string
	// AllowDifferentImplementation is used only by the explicit `--target current`
	// rerun path. Evidence admission on the original broken implementation keeps
	// this false and must match the immutable spec fingerprint.
	AllowDifferentImplementation bool
	Now                          func() time.Time
}

// RunQAReproduction materializes an immutable authored-test bundle in a fresh
// isolated copy and runs the frozen command without a shell.
func RunQAReproduction(ctx context.Context, req QAReproductionRequest) (QAReproductionRun, error) {
	if err := ValidateQAReproductionSpec(req.Spec, req.Budgets); err != nil {
		return QAReproductionRun{}, NewQAError(QAErrorMalformedEvidence, "run reproduction", err.Error(), err)
	}
	if err := ValidateQATestBundle(req.Bundle, req.Spec, req.Budgets); err != nil {
		return QAReproductionRun{}, NewQAError(QAErrorMalformedEvidence, "run reproduction", err.Error(), err)
	}
	if req.Runner == nil {
		req.Runner = pprocess.DirectRunner{}
	}
	if req.Now == nil {
		req.Now = func() time.Time { return time.Now().UTC() }
	}
	limits := pprocess.IsolationLimits{MaxFiles: req.Budgets.TreeFiles, MaxBytes: req.Budgets.TreeBytes, MaxFileSize: req.Budgets.FileBytes, Timeout: req.Budgets.ShardTimeout}
	targetBefore, err := pprocess.IdentifyTree(ctx, req.TargetRoot, limits)
	currentTargetID, identityErr := targetIdentity(req.TargetRoot)
	if err != nil || identityErr != nil || currentTargetID != req.ExpectedTargetID || !req.AllowDifferentImplementation && currentTargetID != req.Spec.ImplementationFingerprint {
		return QAReproductionRun{}, NewQAError(QAErrorStaleInput, "run reproduction", "target identity does not match the frozen reproduction", err)
	}
	workspace, err := pprocess.CreateIsolation(ctx, pprocess.IsolationRequest{SourceRoot: req.TargetRoot, ParentDir: req.WorkspaceParent, Prefix: req.Bundle.ID, ProtectedRoots: append(req.ProtectedRoots, req.TargetRoot), Limits: limits})
	if err != nil {
		return QAReproductionRun{}, NewQAError(QAErrorPermissionDenied, "run reproduction", "cannot create a contained reproduction workspace", err)
	}
	cleanup := QACleanupFacts{Attempted: true}
	defer func() {
		if !cleanup.Complete {
			_ = workspace.Cleanup()
		}
	}()
	if !workspace.Capabilities.PrivateWorkspace || !workspace.Capabilities.ContainedCopy || !workspace.Capabilities.DescendantCleanup || !workspace.Capabilities.WorkspaceRemoval || !workspace.Capabilities.NativeProtectedRootDeny {
		result := workspace.Cleanup()
		return QAReproductionRun{}, NewQAError(QAErrorAdmissionBlocked, "run reproduction", "host isolation cannot prove required containment", fmt.Errorf("cleanup complete: %t", result.Complete))
	}
	for _, file := range req.Bundle.Files {
		path, resolveErr := workspace.Resolve(file.Path)
		if resolveErr != nil {
			return QAReproductionRun{}, NewQAError(QAErrorPermissionDenied, "run reproduction", "authored test path escapes the workspace", resolveErr)
		}
		if mkdirErr := os.MkdirAll(filepath.Dir(path), 0o700); mkdirErr != nil {
			return QAReproductionRun{}, mkdirErr
		}
		if writeErr := os.WriteFile(path, []byte(file.Content), 0o600); writeErr != nil {
			return QAReproductionRun{}, writeErr
		}
	}
	changed, err := workspace.ChangedPaths(ctx, limits)
	if err != nil {
		return QAReproductionRun{}, NewQAError(QAErrorPermissionDenied, "run reproduction", "cannot verify authored test scope", err)
	}
	for _, path := range changed {
		if !qaPathApproved(path, req.Spec.ApprovedTestPaths) {
			return QAReproductionRun{}, NewQAError(QAErrorPermissionDenied, "run reproduction", "authored test materialization changed a non-test path", nil)
		}
	}
	executable, err := exec.LookPath(req.Spec.Command.Executable)
	if err != nil {
		return QAReproductionRun{}, NewQAError(QAErrorAdmissionBlocked, "run reproduction", "frozen test executable is unavailable", err)
	}
	workdir := req.Spec.Command.WorkingDirectory
	if workdir == "" {
		workdir = "."
	}
	environment := make(map[string]string, len(req.Spec.Command.Environment))
	for _, name := range req.Spec.Command.Environment {
		if strings.ContainsAny(name, "=\x00\r\n") {
			return QAReproductionRun{}, NewQAError(QAErrorPermissionDenied, "run reproduction", "frozen environment name is invalid", nil)
		}
		if value, ok := os.LookupEnv(name); ok {
			environment[name] = value
		}
	}
	runtimeRoot, err := workspace.Resolve(".ultraplan-test-runtime")
	if err != nil {
		return QAReproductionRun{}, err
	}
	for _, path := range []string{runtimeRoot, filepath.Join(runtimeRoot, "cache"), filepath.Join(runtimeRoot, "tmp"), filepath.Join(runtimeRoot, "home"), filepath.Join(runtimeRoot, "gopath")} {
		if err := os.MkdirAll(path, 0o700); err != nil {
			return QAReproductionRun{}, err
		}
	}
	environment["HOME"] = filepath.Join(runtimeRoot, "home")
	environment["GOCACHE"] = filepath.Join(runtimeRoot, "cache")
	environment["GOPATH"] = filepath.Join(runtimeRoot, "gopath")
	environment["GOTMPDIR"] = filepath.Join(runtimeRoot, "tmp")
	environment["TMPDIR"] = filepath.Join(runtimeRoot, "tmp")
	started := req.Now().UTC()
	result, runErr := workspace.Run(ctx, req.Runner, workdir, pprocess.Request{Executable: executable, Args: append([]string(nil), req.Spec.Command.Args...), Env: pprocess.SortedEnvironment(environment), Timeout: req.Spec.Command.Timeout, StdoutLimit: req.Spec.Command.OutputLimit, StderrLimit: req.Spec.Command.OutputLimit, CleanupGrace: req.Budgets.CleanupTimeout})
	argsDigest := sha256.Sum256([]byte(strings.Join(req.Spec.Command.Args, "\x00")))
	stdout, stderr := config.RedactValue("qa.reproduction.stdout", result.Stdout), config.RedactValue("qa.reproduction.stderr", result.Stderr)
	redactions := 0
	if stdout != result.Stdout {
		redactions++
	}
	if stderr != result.Stderr {
		redactions++
	}
	stdoutDigest := sha256.Sum256([]byte(stdout))
	stderrDigest := sha256.Sum256([]byte(stderr))
	command := QACommandResult{Executable: filepath.Base(executable), ArgsDigest: hex.EncodeToString(argsDigest[:]), ExitCode: result.ExitCode, Duration: req.Now().UTC().Sub(started), StdoutDigest: hex.EncodeToString(stdoutDigest[:]), StderrDigest: hex.EncodeToString(stderrDigest[:]), Stdout: stdout, Stderr: stderr, OutputBytes: len(stdout) + len(stderr), Truncated: result.StdoutTruncated || result.StderrTruncated, Redacted: redactions > 0, RedactionCount: redactions, TimedOut: result.TimedOut, Cancelled: result.Cancelled, CleanupAttempted: result.CleanupAttempted, CleanupComplete: result.CleanupComplete}
	if runErr != nil && !command.TimedOut && !command.Cancelled && command.ExitCode == 0 {
		command.ExitCode = 1
	}
	outcome, reason := ClassifyQAReproductionResult(command, req.Spec.PredictedFailure)
	if removeErr := removeQAReproductionRuntime(runtimeRoot); removeErr != nil {
		outcome, reason = QAEvidenceInconclusive, "runtime_cleanup_incomplete"
	}
	postChanges, changeErr := workspace.ChangedPaths(context.WithoutCancel(ctx), limits)
	if changeErr != nil {
		outcome, reason = QAEvidenceInconclusive, "workspace_changes_incomplete"
	}
	for _, path := range postChanges {
		if !qaPathApproved(path, req.Spec.ApprovedTestPaths) {
			outcome, reason = QAEvidenceInconclusive, "source_change_detected"
		}
	}
	cleanupResult := workspace.Cleanup()
	cleanup = QACleanupFacts{Attempted: true, DescendantsTerminated: command.CleanupComplete, WorkspaceRemoved: cleanupResult.Complete, Complete: command.CleanupComplete && cleanupResult.Complete, Diagnostic: cleanupResult.Error}
	if !cleanup.Complete {
		outcome, reason = QAEvidenceInconclusive, "cleanup_uncertain"
	}
	targetAfter, targetErr := pprocess.IdentifyTree(context.WithoutCancel(ctx), req.TargetRoot, limits)
	currentTargetAfter, currentTargetErr := targetIdentity(req.TargetRoot)
	if targetErr != nil || currentTargetErr != nil || targetAfter.Digest != targetBefore.Digest || currentTargetAfter != currentTargetID {
		outcome, reason = QAEvidenceInconclusive, "target_drift"
	}
	completed := req.Now().UTC()
	run := QAReproductionRun{SchemaVersion: QAEvidenceSchemaVersion, SpecID: req.Spec.ID, TestBundleID: req.Bundle.ID, TargetIdentity: currentTargetID, Result: command, Signature: req.Spec.PredictedFailure, Outcome: outcome, ReasonCode: reason, Cleanup: cleanup, CompletedAt: completed}
	run.ID, err = NewQAV2ID("run", req.Project, req.Sprint, req.Bundle.ID, struct {
		Target, Args, Stdout, Stderr, Reason string
		Exit                                 int
		Completed                            time.Time
	}{run.TargetIdentity, command.ArgsDigest, command.StdoutDigest, command.StderrDigest, reason, command.ExitCode, completed})
	if err != nil {
		return QAReproductionRun{}, err
	}
	if err := ValidateQAReproductionRun(run, req.Spec, req.Bundle); err != nil {
		return QAReproductionRun{}, NewQAError(QAErrorMalformedEvidence, "run reproduction", err.Error(), err)
	}
	return run, nil
}

func removeQAReproductionRuntime(root string) error {
	if err := filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if entry.IsDir() {
			return os.Chmod(path, 0o700)
		}
		return nil
	}); err != nil {
		return err
	}
	return os.RemoveAll(root)
}

func (s Service) RerunQATest(ctx context.Context, projectRef, sprintRef, testID string, token QAWriterToken) (QAReproductionRun, error) {
	if err := token.Validate(); err != nil {
		return QAReproductionRun{}, NewQAError(QAErrorConflict, "rerun authored test", err.Error(), err)
	}
	sp, err := s.resolveMutationSprint(projectRef, sprintRef)
	if err != nil {
		return QAReproductionRun{}, err
	}
	store := NewQAStore(s.root, sp)
	state, err := store.LoadState()
	if err != nil {
		return QAReproductionRun{}, err
	}
	qaMap, err := store.LoadMap(state.CurrentAttemptID)
	if err != nil {
		return QAReproductionRun{}, err
	}
	spec, bundle, err := store.LoadTestBundle(state.CurrentAttemptID, testID, qaMap.Budgets)
	if err != nil {
		return QAReproductionRun{}, err
	}
	manifest, findings, err := s.PrepareReview(projectRef, sprintRef, ReviewRequest{})
	if err != nil || len(findings) > 0 {
		return QAReproductionRun{}, NewQAError(QAErrorStaleInput, "rerun authored test", "current implementation target is unavailable", err)
	}
	workspaceParent, err := os.MkdirTemp("", "ultraplan-qa-rerun-")
	if err != nil {
		return QAReproductionRun{}, err
	}
	defer os.RemoveAll(workspaceParent)
	targetID, err := targetIdentity(manifest.Target)
	if err != nil {
		return QAReproductionRun{}, err
	}
	// A persistent rerun may target the current implementation after repair. The
	// immutable spec remains unchanged; the run records the selected target.
	run, err := RunQAReproduction(ctx, QAReproductionRequest{Project: sp.Project, Sprint: sp.Slug, TargetRoot: manifest.Target, WorkspaceParent: workspaceParent, ProtectedRoots: []string{s.root, manifest.Target}, Spec: spec, Bundle: bundle, Budgets: qaMap.Budgets, ExpectedTargetID: targetID, AllowDifferentImplementation: true, Now: s.now})
	if err != nil {
		return QAReproductionRun{}, err
	}
	// Restore the immutable signature/spec identity for validation and storage.
	run.SpecID = spec.ID
	fence := s.verificationWriterFence
	if fence == nil {
		expected := token
		fence = func(got QAWriterToken) error {
			if got != expected {
				return fmt.Errorf("writer token does not own this rerun")
			}
			return nil
		}
	}
	store = store.WithWriterFence(fence)
	if err := store.PublishReproductionRun(state.CurrentAttemptID, spec, bundle, run, token); err != nil {
		return QAReproductionRun{}, err
	}
	return run, nil
}

package sprint

import "fmt"

// VerificationPhase identifies verification work independently from the
// authored planning sequence. Conformance review keeps the existing review
// implementation and public compatibility contracts.
type VerificationPhase string

const (
	VerificationPhasePerformance       VerificationPhase = "performance"
	VerificationPhaseConformanceReview VerificationPhase = "conformance-review"
	VerificationPhaseQA                VerificationPhase = "qa"
	VerificationPhaseRepair            VerificationPhase = "repair"
)

func VerificationPhases() []VerificationPhase {
	return []VerificationPhase{
		VerificationPhasePerformance,
		VerificationPhaseConformanceReview,
		VerificationPhaseQA,
		VerificationPhaseRepair,
	}
}

func ParseVerificationPhase(value string) (VerificationPhase, error) {
	switch value {
	case string(VerificationPhasePerformance):
		return VerificationPhasePerformance, nil
	case "review", string(VerificationPhaseConformanceReview):
		return VerificationPhaseConformanceReview, nil
	case string(VerificationPhaseQA):
		return VerificationPhaseQA, nil
	case string(VerificationPhaseRepair):
		return VerificationPhaseRepair, nil
	default:
		return "", fmt.Errorf("unsupported verification phase %q", value)
	}
}

// CompatibilityStage maps only shipped legacy stage capabilities. Performance,
// QA, and repair have no PlanningStage identity and cannot enter planning
// order through this adapter.
func (p VerificationPhase) CompatibilityStage() (PlanningStage, bool) {
	if p == VerificationPhaseConformanceReview {
		return StageReview, true
	}
	return "", false
}

func verificationPhaseForStage(stage PlanningStage) (VerificationPhase, bool) {
	if stage == StageReview {
		return VerificationPhaseConformanceReview, true
	}
	return "", false
}

package sprint

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

type VerifyRequest struct {
	To       PlanningStage
	DryRun   bool
	Review   ReviewRequest
	Smoke    SmokeRequest
	Progress func(FlowProgress)
}

type VerifyResult struct {
	Project      string             `json:"project"`
	Sprint       string             `json:"sprint"`
	To           PlanningStage      `json:"to"`
	DryRun       bool               `json:"dry_run"`
	ReviewResult *ReviewResult      `json:"review_result,omitempty"`
	SmokeResult  *SmokeResult       `json:"smoke_result,omitempty"`
	Verification VerificationStatus `json:"verification"`
}

// Verify is the sole review-to-smoke transition. It requires complete execute
// evidence, reuses current canonical review evidence, and applies the smoke gate.
func (s Service) Verify(ctx context.Context, projectRef, sprintRef string, req VerifyRequest) (VerifyResult, error) {
	if !req.DryRun {
		lockedCtx, release, lockErr := s.acquireMutationContext(ctx, projectRef, sprintRef)
		if lockErr != nil {
			return VerifyResult{}, lockErr
		}
		defer release()
		ctx = lockedCtx
	}
	if req.To == "" {
		req.To = StageSmoke
	}
	if req.To != StageReview && req.To != StageSmoke {
		return VerifyResult{}, fmt.Errorf("verify target must be review or smoke")
	}
	result := VerifyResult{Project: projectRef, Sprint: sprintRef, To: req.To, DryRun: req.DryRun}
	if err := s.requireCompleteExecute(projectRef, sprintRef); err != nil {
		return result, err
	}
	if err := s.requirePerformanceGate(projectRef, sprintRef); err != nil {
		return result, err
	}
	status, statusErr := s.VerificationStatus(projectRef, sprintRef)
	if statusErr != nil && !errors.Is(statusErr, ErrFlowStateMissing) {
		return result, statusErr
	}
	if statusErr == nil {
		result.Verification = status
	}
	currentReview := statusErr == nil && verificationStageCurrent(status.Review, string(ReviewCompleted)) && !req.Review.Restart
	if !currentReview {
		if req.Progress != nil {
			req.Progress(FlowProgress{Stage: StageReview, State: "running", Message: "obtaining current review evidence"})
		}
		reviewReq := req.Review
		reviewReq.DryRun = req.DryRun
		review, err := s.Review(ctx, projectRef, sprintRef, reviewReq)
		result.ReviewResult = &review
		allowDiagnosticContinuation := req.To == StageSmoke && review.Status == ReviewCompleted && review.Verdict == ReviewFail && req.Smoke.ForceReview && req.Smoke.OverrideConfirmed && strings.TrimSpace(req.Smoke.OverrideRationale) != ""
		if err != nil && !allowDiagnosticContinuation {
			return result, err
		}
	} else if req.Progress != nil {
		req.Progress(FlowProgress{Stage: StageReview, State: "skipped", Message: "current review evidence is acceptable"})
	}
	if req.To == StageReview || req.DryRun {
		if !req.DryRun {
			result.Verification, _ = s.VerificationStatus(projectRef, sprintRef)
		}
		return result, nil
	}
	currentSmoke := statusErr == nil && verificationStageCurrent(status.Smoke, string(SmokeCompleted))
	if currentSmoke {
		if req.Progress != nil {
			req.Progress(FlowProgress{Stage: StageSmoke, State: "skipped", Message: "current smoke evidence is acceptable"})
		}
		result.Verification = status
		return result, nil
	}
	if req.Progress != nil {
		req.Progress(FlowProgress{Stage: StageSmoke, State: "running", Message: "evaluating review gate and running smoke"})
	}
	smokeReq := req.Smoke
	smoke, err := s.RunSmoke(ctx, projectRef, sprintRef, smokeReq)
	result.SmokeResult = &smoke
	result.Verification, _ = s.VerificationStatus(projectRef, sprintRef)
	return result, err
}

func verificationStageCurrent(stage VerificationStage, completedStatus string) bool {
	return stage.Fresh && stage.ExecutionStatus == completedStatus
}

func (s Service) requireCompleteExecute(projectRef, sprintRef string) error {
	sp, _, _, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return err
	}
	state, err := LoadExecuteRunState(s.root, sp)
	if err != nil {
		path, pathErr := ExecuteRunStatePath(s.root, sp)
		if pathErr == nil {
			var summary struct {
				Status string   `json:"status"`
				Files  []string `json:"files"`
			}
			if data, readErr := os.ReadFile(path); readErr == nil && json.Unmarshal(data, &summary) == nil && (summary.Status == "complete" || summary.Status == "completed") && len(summary.Files) > 0 {
				content, artifactErr := s.store.ReadArtifact(sp, StageExecute)
				if artifactErr == nil && strings.TrimSpace(content) != "" {
					return nil
				}
			}
		}
		return fmt.Errorf("execute evidence is incomplete: %w", err)
	}
	if len(state.Tasks) == 0 {
		return fmt.Errorf("execute evidence is incomplete: no planned tasks")
	}
	for _, task := range state.Tasks {
		if task.Status != ExecuteTaskComplete && task.Status != ExecuteTaskDeferred {
			return fmt.Errorf("execute evidence is incomplete: task %q is %s", task.Identity.Name, task.Status)
		}
	}
	data, err := s.store.ReadArtifact(sp, StageExecute)
	if err != nil || strings.TrimSpace(data) == "" {
		return fmt.Errorf("execute evidence is incomplete: execute.md is missing")
	}
	return nil
}

func (s Service) ExecuteComplete(projectRef, sprintRef string) (bool, error) {
	err := s.requireCompleteExecute(projectRef, sprintRef)
	if err != nil {
		return false, nil
	}
	return true, nil
}

func (s Service) VerificationStatus(projectRef, sprintRef string) (VerificationStatus, error) {
	sp, _, _, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return VerificationStatus{}, err
	}
	out := VerificationStatus{Project: sp.Project, Sprint: sp.Slug}
	out.Review = VerificationStage{Stage: StageReview, ExecutionStatus: "missing", Artifact: ArtifactRelPath(sp, StageReview), NextAction: "Run review."}
	out.Smoke = VerificationStage{Stage: StageSmoke, ExecutionStatus: "missing", Artifact: ArtifactRelPath(sp, StageSmoke), NextAction: "Run smoke after a current acceptable review."}
	state, err := LoadFlowState(s.root, sp)
	if err != nil {
		return out, err
	}
	// Status derives expired-attempt truth without mutating durable state.
	// The next explicit review/smoke operation owns any persisted transition.
	reconcileExpiredAttempts(&state, s.now().UTC())
	malformed := false
	if state.Review != nil {
		r := state.Review
		out.Review.ExecutionStatus, out.Review.Verdict = string(r.Status), string(r.Verdict)
		out.Review.InputFingerprint, out.Review.ArtifactDigest = r.Fingerprint, r.ArtifactDigest
		out.Review.ActiveAttempt, out.Review.LastAttempt = r.ActiveAttempt, r.LastAttempt
		if r.Resume != nil {
			out.Review.Total = len(r.Resume.Coverage)
			for _, checkpoint := range r.Resume.Coverage {
				if checkpoint.Status == AttemptCompleted {
					out.Review.Completed++
				}
				if checkpoint.SessionID != "" && checkpoint.Status != AttemptCompleted {
					out.Review.RetainedSessions++
				}
			}
			out.Review.Resumable = out.Review.Completed > 0
		}
		manifest, findings, prepareErr := s.PrepareReview(projectRef, sprintRef, ReviewRequest{})
		if prepareErr != nil || len(findings) > 0 {
			out.Review.FreshnessReasons = append(out.Review.FreshnessReasons, "governed review inputs are unavailable or invalid")
		} else if strictCompletedReviewSnapshotFreshness && manifest.Fingerprint != r.Fingerprint {
			out.Review.FreshnessReasons = append(out.Review.FreshnessReasons, "review input fingerprint changed")
		}
		if r.Resume != nil && (prepareErr != nil || len(findings) > 0 || manifest.Fingerprint != r.Resume.InputFingerprint || manifest.Model != r.Resume.Model) {
			out.Review.Resumable = false
		}
		data, readErr := os.ReadFile(mustArtifactPath(s.root, sp, StageReview))
		if readErr != nil {
			out.Review.FreshnessReasons = append(out.Review.FreshnessReasons, "review artifact is missing")
		} else {
			if r.ArtifactDigest == "" || hashBytes(data) != r.ArtifactDigest {
				out.Review.FreshnessReasons = append(out.Review.FreshnessReasons, "review artifact digest changed")
			}
			validationManifest := manifest
			if !strictCompletedReviewSnapshotFreshness {
				// Validate the canonical artifact against the fingerprint recorded when
				// it completed, rather than a later filesystem snapshot.
				validationManifest.Fingerprint = r.Fingerprint
			}
			if prepareErr == nil && len(findings) == 0 && len(ValidateReviewContent(string(data), validationManifest)) > 0 {
				malformed = true
				out.Review.FreshnessReasons = append(out.Review.FreshnessReasons, "review artifact is malformed")
			}
		}
		out.Review.Fresh = len(out.Review.FreshnessReasons) == 0 && r.LastComplete != nil
		if !out.Review.Fresh {
			if out.Review.Resumable {
				out.Review.NextAction = fmt.Sprintf("Resume review from %d/%d validated coverage (%d retained sessions), or restart it explicitly.", out.Review.Completed, out.Review.Total, out.Review.RetainedSessions)
			} else {
				out.Review.NextAction = "Rerun review using the current governed inputs."
			}
		} else {
			out.Review.NextAction = "Review is current."
		}
	}
	if state.Smoke != nil {
		sm := state.Smoke
		out.Smoke.ExecutionStatus, out.Smoke.Verdict = string(sm.Status), string(sm.Verdict)
		out.Smoke.InputFingerprint, out.Smoke.ArtifactDigest, out.Smoke.RunID = sm.InputFingerprint, sm.ArtifactDigest, sm.RunID
		out.Smoke.Issues, out.Smoke.Evidence, out.Smoke.Override = append([]SmokeIssue(nil), sm.Issues...), append([]EvidenceReference(nil), sm.Evidence...), sm.Override
		out.Smoke.ActiveAttempt, out.Smoke.LastAttempt = sm.ActiveAttempt, sm.LastAttempt
		if !out.Review.Fresh {
			out.Smoke.FreshnessReasons = append(out.Smoke.FreshnessReasons, "review evidence is not current")
		}
		data, readErr := os.ReadFile(mustArtifactPath(s.root, sp, StageSmoke))
		if readErr != nil {
			out.Smoke.FreshnessReasons = append(out.Smoke.FreshnessReasons, "smoke artifact is missing")
		} else {
			if sm.ArtifactDigest == "" || hashBytes(data) != sm.ArtifactDigest {
				out.Smoke.FreshnessReasons = append(out.Smoke.FreshnessReasons, "smoke artifact digest changed")
			}
			if len(ValidateSmokeContent(string(data))) > 0 {
				malformed = true
				out.Smoke.FreshnessReasons = append(out.Smoke.FreshnessReasons, "smoke artifact is malformed")
			}
		}
		if sm.LastComplete == nil || sm.InputFingerprint == "" {
			out.Smoke.FreshnessReasons = append(out.Smoke.FreshnessReasons, "smoke input fingerprint is unavailable")
		} else if strictCompletedSmokeSnapshotFreshness {
			if fingerprint, identityErr := refreshEvidenceFingerprint(sm.LastComplete.Evidence); identityErr != nil || fingerprint != sm.InputFingerprint {
				out.Smoke.FreshnessReasons = append(out.Smoke.FreshnessReasons, "smoke inputs or external evidence changed")
			}
		}
		out.Smoke.Fresh = len(out.Smoke.FreshnessReasons) == 0
		if !out.Smoke.Fresh {
			out.Smoke.NextAction = "Rerun the required containing smoke suite."
		} else {
			out.Smoke.NextAction = "Smoke evidence is current."
		}
	}
	out.Assessment, out.NextAction = deriveAssessment(out.Review, out.Smoke, malformed)
	return out, nil
}

func deriveAssessment(review, smoke VerificationStage, malformed bool) (OverallAssessment, string) {
	if malformed {
		return AssessmentBlocked, "Repair or regenerate malformed canonical verification evidence."
	}
	if review.Fresh && review.Verdict == string(ReviewFail) {
		return AssessmentFail, "Resolve review findings and rerun review; diagnostic smoke cannot change this result."
	}
	if review.Fresh && review.Verdict == string(ReviewVerdictBlocked) {
		return AssessmentBlocked, "Satisfy the review prerequisite and rerun review."
	}
	if !review.Fresh || review.ExecutionStatus != string(ReviewCompleted) || !smoke.Fresh || smoke.ExecutionStatus != string(SmokeCompleted) {
		if !review.Fresh || review.ExecutionStatus != string(ReviewCompleted) {
			return AssessmentIncomplete, "Run or retry review, the earliest non-current verification stage."
		}
		return AssessmentIncomplete, "Run or retry smoke, the earliest non-current verification stage."
	}
	switch SmokeVerdict(smoke.Verdict) {
	case SmokeFailVerdict:
		return AssessmentFail, "Resolve the classified failure and rerun the required containing suite."
	case SmokeBlockedVerdict:
		return AssessmentBlocked, "Restore smoke prerequisites, coverage, or evidence and rerun smoke."
	case SmokeNotApplicable:
		return AssessmentNotApplicable, "No runtime smoke is applicable; retain the current review rationale."
	case SmokePassWithOpenIssues:
		return AssessmentPassWithFindings, "Resolve linked relevant issues and rerun narrow plus containing scope."
	case SmokePass:
		if ReviewVerdict(review.Verdict) == ReviewPassWithFindings {
			return AssessmentPassWithFindings, "Address review findings if a clean assessment is required."
		}
		return AssessmentPass, "No verification action required."
	default:
		return AssessmentBlocked, "Repair the unsupported smoke verdict."
	}
}

func smokeInputFingerprint(p smokePrepared, result SmokeResult) string {
	refs := smokeIdentityReferences(p, result)
	fingerprint, _ := refreshEvidenceFingerprint(refs)
	return fingerprint
}

func smokeIdentityReferences(p smokePrepared, result SmokeResult) []EvidenceReference {
	refs := []EvidenceReference{
		{Kind: "file", Path: p.ManifestPath},
		{Kind: "file", Path: filepath.Join(p.Sprint.Path, "review.md")},
		{Kind: "fact", Path: "review-fingerprint", Digest: result.ReviewFingerprint},
		{Kind: "fact", Path: "review-verdict", Digest: string(result.ReviewVerdict)},
		{Kind: "fact", Path: "scope", Digest: result.ScopeKind + ":" + result.Scope},
